#requires -Version 7.2
#requires -RunAsAdministrator
# whispr exit flag UI patch 1.0.0. Close tray only; background VPN can keep running.
[CmdletBinding()]
param([switch]$Restore,[string]$Backup,[switch]$NoLaunch)
$ErrorActionPreference='Stop'
Set-StrictMode -Version 3

# Embedded image resources: no runtime downloads, font emoji or extra installed files.
$script:HybridFlagRuntime = @'
# BEGIN whispr exit flags v1
$script:hybridExitFlagImages=@{}
$script:hybridExitFlagPngs=@{
    US=''
    GB=''
    DE=''
    SG=''
    AU=''
    XX=''
}
function Get-HybridExitFlagCountry([string]$Alias){
    $countries=@{nyc1='US';lon1='GB';fkt1='DE';sgp1='SG';syd1='AU'}
    if($countries.ContainsKey($Alias)){return $countries[$Alias]}
    return 'XX'
}
function Get-HybridExitFlagImage([string]$Alias){
    $country=Get-HybridExitFlagCountry $Alias
    if(-not $script:hybridExitFlagImages.ContainsKey($country)){
        $bytes=[Convert]::FromBase64String($script:hybridExitFlagPngs[$country])
        $stream=[IO.MemoryStream]::new($bytes,$false);$source=$null
        try{
            $source=[Drawing.Image]::FromStream($stream)
            $script:hybridExitFlagImages[$country]=[Drawing.Bitmap]::new($source)
        }finally{if($source){$source.Dispose()};$stream.Dispose()}
    }
    return $script:hybridExitFlagImages[$country]
}
function Clear-HybridExitFlagImages {
    foreach($image in $script:hybridExitFlagImages.Values){$image.Dispose()}
    $script:hybridExitFlagImages.Clear()
}
# END whispr exit flags v1
'@

function Add-HybridFlagsToTraySource([string]$Source){
    $nl=[string][char]10
    $begin='# BEGIN whispr exit flags v1';$end='# END whispr exit flags v1'
    $pattern=[regex]::Escape($begin)+'[\s\S]*?'+[regex]::Escape($end)
    $blocks=[regex]::Matches($Source,$pattern)
    $runtime=$script:HybridFlagRuntime.Trim()
    if($blocks.Count -eq 1){
        $m=$blocks[0];$Source=$Source.Remove($m.Index,$m.Length).Insert($m.Index,$runtime)
    }elseif($blocks.Count -eq 0 -and -not $Source.Contains($begin) -and -not $Source.Contains($end)){
        $anchor='$script:icons=@{};$script:locked=$false;$script:context=$null'
        if([regex]::Matches($Source,[regex]::Escape($anchor)).Count -ne 1){throw 'Unrecognised tray resource initialisation. No files changed.'}
        $Source=$Source.Replace($anchor,$anchor+$nl+$runtime)
    }else{throw 'Ambiguous or incomplete existing flag block. No files changed.'}

    $anchor='    $script:exitItems=@{}'
    $margin='    $script:exitMenu.DropDown.ShowImageMargin=$true'
    if(-not $Source.Contains($margin)){
        if([regex]::Matches($Source,[regex]::Escape($anchor)).Count -ne 1){throw 'Unrecognised exit menu. No files changed.'}
        $Source=$Source.Replace($anchor,($anchor,$margin,'    $script:exitMenu.DropDown.ShowCheckMargin=$true','    $script:exitMenu.DropDown.ImageScalingSize=[Drawing.Size]::new(24,16)' -join $nl))
    }
    $anchor='        $entry=[Windows.Forms.ToolStripMenuItem]::new($alias);$entry.Tag=$alias'
    $image='        $entry.Image=Get-HybridExitFlagImage $alias'
    if(-not $Source.Contains($image)){
        if([regex]::Matches($Source,[regex]::Escape($anchor)).Count -ne 1){throw 'Unrecognised exit entries. No files changed.'}
        $Source=$Source.Replace($anchor,$anchor+$nl+$image)
    }
    $anchor='    foreach($icon in $script:icons.Values){$icon.Dispose()}'
    $cleanup='    Clear-HybridExitFlagImages'
    if(-not $Source.Contains($cleanup)){
        if([regex]::Matches($Source,[regex]::Escape($anchor)).Count -ne 1){throw 'Unrecognised tray cleanup. No files changed.'}
        $Source=$Source.Replace($anchor,$cleanup+$nl+$anchor)
    }
    $tokens=$null;$errors=$null
    [void][Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors)
    if($errors.Count){throw 'Updated tray failed its PowerShell syntax check. No files changed.'}
    return $Source
}


$homeDir=Join-Path $env:ProgramFiles 'whispr Hybrid VPN'
$stateDir=Join-Path $env:ProgramData 'whispr-hybrid'
foreach($dir in @($homeDir,$stateDir)){
    $item=Get-Item -LiteralPath $dir -Force
    if($item -isnot [IO.DirectoryInfo] -or $item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Unexpected application/state directory.'}
    if((Get-Acl -LiteralPath $dir).GetOwner([Security.Principal.SecurityIdentifier]).Value -notin @('S-1-5-18','S-1-5-32-544')){throw 'Unexpected directory owner.'}
    if((Get-Content -LiteralPath (Join-Path $dir 'install-owner.txt') -Raw).Trim() -ne 'whispr-hybrid-schema-1'){throw 'Application ownership marker differs.'}
}
. "$homeDir/client/Common.ps1";. "$homeDir/tray/Model.ps1"
Assert-HybridManifest $homeDir;Assert-TrayAddon $homeDir
$mutex=[Threading.Mutex]::new($false,'Global\whisprHybridTray010');$locked=$false
$files=@('Tray.ps1','SHA256SUMS.json','tray/ADDON-SHA256SUMS.json')
function Read-FlagJson([string]$Path){return (Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json -AsHashtable)}
function Write-FlagJson($Value,[string]$Path){
    $temp=$Path+'.flags-'+[guid]::NewGuid().ToString('N')+'.tmp'
    try{[IO.File]::WriteAllText($temp,($Value|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $temp -Destination $Path -Force}
    finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
}
try{
    try{$locked=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$locked=$true}
    if(-not $locked){throw 'Choose Close tray only - keep VPN running, then run this patch again.'}
    foreach($relative in $files){
        $path=Join-Path $homeDir $relative
        if((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Unexpected destination reparse point.'}
        if((Get-Item -LiteralPath (Split-Path $path -Parent) -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Unexpected destination directory reparse point.'}
    }
    $backupRoot=Join-Path $stateDir 'flag-backups'
    if((Test-Path -LiteralPath $backupRoot) -and ((Get-Item -LiteralPath $backupRoot -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Unexpected backup-directory reparse point.'}
    if($Restore){
        if(-not $Backup){
            $last=Get-ChildItem -LiteralPath $backupRoot -Directory -Filter 'flags-*'|Where-Object {Test-Path -LiteralPath (Join-Path $_.FullName 'restore.json')}|Sort-Object CreationTimeUtc -Descending|Select-Object -First 1
            if(-not $last){throw 'No completed flag-patch backup exists.'};$Backup=$last.FullName
        }
        $Backup=[IO.Path]::GetFullPath($Backup)
        if((Split-Path $Backup -Parent) -ne $backupRoot -or (Get-Item -LiteralPath $Backup -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Use a flag backup from this installation.'}
        $meta=Read-FlagJson (Join-Path $Backup 'restore.json')
        if($meta.Schema -ne 1 -or $meta.Before.Count -ne 3 -or $meta.After.Count -ne 3){throw 'Unexpected restore metadata.'}
        foreach($relative in $files){
            if(-not $meta.Before.ContainsKey($relative) -or -not $meta.After.ContainsKey($relative)){throw 'Incomplete restore metadata.'}
            if((Get-FileHash -LiteralPath (Join-Path $homeDir $relative)).Hash -ne $meta.After[$relative]){throw 'Files changed since the flag patch; refusing to overwrite a later update.'}
            if((Get-FileHash -LiteralPath (Join-Path $Backup $relative)).Hash -ne $meta.Before[$relative]){throw 'Backup integrity check failed.'}
        }
        foreach($relative in $files){Copy-Item -LiteralPath (Join-Path $Backup $relative) -Destination (Join-Path $homeDir $relative) -Force}
        Assert-HybridManifest $homeDir;Assert-TrayAddon $homeDir
        Write-Host 'Previous tray appearance restored. Background VPN retained.' -ForegroundColor Green
    }else{
        $source=Get-Content -LiteralPath "$homeDir/Tray.ps1" -Raw
        $updated=Add-HybridFlagsToTraySource $source
        if($source -ceq $updated){Write-Host 'Flag icons already installed. No files changed.' -ForegroundColor Green}
        else{
            $backup=Join-Path $backupRoot ('flags-'+[guid]::NewGuid().ToString('N'));[void](New-Item -ItemType Directory -Path $backup -Force)
            $before=@{}
            foreach($relative in $files){
                $before[$relative]=(Get-FileHash -LiteralPath (Join-Path $homeDir $relative)).Hash
                $dest=Join-Path $backup $relative;[void](New-Item -ItemType Directory -Path (Split-Path $dest -Parent) -Force)
                Copy-Item -LiteralPath (Join-Path $homeDir $relative) -Destination $dest
            }
            try{
                [IO.File]::WriteAllText("$homeDir/Tray.ps1",$updated,[Text.UTF8Encoding]::new($false))
                $core=Read-FlagJson "$homeDir/SHA256SUMS.json";$addon=Read-FlagJson "$homeDir/tray/ADDON-SHA256SUMS.json"
                $hash=(Get-FileHash -LiteralPath "$homeDir/Tray.ps1").Hash
                if($core.ContainsKey('Tray.ps1')){$core['Tray.ps1']=$hash};$addon['Tray.ps1']=$hash
                Write-FlagJson $core "$homeDir/SHA256SUMS.json";Write-FlagJson $addon "$homeDir/tray/ADDON-SHA256SUMS.json"
                Assert-HybridManifest $homeDir;Assert-TrayAddon $homeDir
                $after=@{};foreach($relative in $files){$after[$relative]=(Get-FileHash -LiteralPath (Join-Path $homeDir $relative)).Hash}
                Write-FlagJson @{Schema=1;Before=$before;After=$after} (Join-Path $backup 'restore.json')
            }catch{
                $failure=$_;foreach($relative in $files){Copy-Item -LiteralPath (Join-Path $backup $relative) -Destination (Join-Path $homeDir $relative) -Force};throw $failure
            }
            Write-Host 'Country flag icons installed. VPN session, keys, profiles, map and sign-in setting retained.' -ForegroundColor Green
            Write-Host "Backup: $backup"
        }
    }
}finally{if($locked){$mutex.ReleaseMutex()};$mutex.Dispose()}
if(-not $NoLaunch){& "$homeDir/Open-Tray.ps1"}
